const seen = new Set();
const games = [];

for (const item of $input.all()) {
  const g = item.json;
  if (!g || g.id === undefined || g.id === null) continue;
  if (g.status !== 'approved') continue;   // Dead-Link-Schutz: nur approved Games sind über /api/games erreichbar
  if (seen.has(g.id)) continue;
  seen.add(g.id);
  games.push({
    id: g.id,
    title: g.title,
    difficulty: g.difficulty,
    topic: g.topic,
    target_role: g.target_role,
    learning_objective: g.learning_objective,
  });
}

return [{ json: { games } }];

// Aggregiert die Tabelle "scores" pro Spieler:
//  - total_score   = Summe aller score-Werte
//  - games_played  = Anzahl abgeschlossener Spiel-Durchläufe
//  - unique_games  = Anzahl unterschiedlicher game_id
//  - streak        = aufeinanderfolgende Kalenderwochen mit mind. 1 gespieltem Game

function weekStart(dateLike) {
  const d = new Date(dateLike);
  if (isNaN(d.getTime())) return null;
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dow = (t.getUTCDay() + 6) % 7;          // Montag = 0
  t.setUTCDate(t.getUTCDate() - dow);
  return t.toISOString().slice(0, 10);
}

const rows = $input.all().map(i => i.json).filter(r => r && r.player_id);

const acc = {};
for (const r of rows) {
  const pid = String(r.player_id);
  if (!acc[pid]) acc[pid] = { total_score: 0, games_played: 0, gameIds: {}, weeks: {} };
  const a = acc[pid];
  a.total_score += Number(r.score) || 0;
  a.games_played += 1;
  if (r.game_id) a.gameIds[String(r.game_id)] = true;
  const wk = r.completed_at ? weekStart(r.completed_at) : null;
  if (wk) a.weeks[wk] = true;
}

// aktuelle Woche (Montag) als Ausgangspunkt
const nowWeek = weekStart(new Date());
const MS_WEEK = 7 * 24 * 60 * 60 * 1000;

const stats = {};
for (const [pid, a] of Object.entries(acc)) {
  let cursor = new Date(nowWeek + 'T00:00:00Z');
  // Kulanz: wurde diese Woche noch nicht gespielt, zaehlt der Streak ab letzter Woche
  if (!a.weeks[cursor.toISOString().slice(0, 10)]) {
    cursor = new Date(cursor.getTime() - MS_WEEK);
  }
  let streak = 0;
  while (a.weeks[cursor.toISOString().slice(0, 10)]) {
    streak += 1;
    cursor = new Date(cursor.getTime() - MS_WEEK);
  }
  stats[pid] = {
    total_score: a.total_score,
    games_played: a.games_played,
    unique_games: Object.keys(a.gameIds).length,
    streak,
  };
}

return [{ json: { stats } }];

const user = $json;
const allGames = $('Collect & Dedupe Games').first().json.games || [];
const allStats = $('Aggregate Player Stats').first().json.stats || {};
const role = (user.role || '').toString().toLowerCase().trim();

const PLATFORM_URL = 'https://aiim-gamification.vercel.app';

const scored = allGames.map((g, idx) => {
  const tr = (g.target_role || '').toString().toLowerCase();
  const match = role && tr && (tr.includes(role) || role.includes(tr)) ? 1 : 0;
  return { g, match, idx };
});
scored.sort((a, b) => (b.match - a.match) || (a.idx - b.idx));
const featured = scored.length ? scored[0].g : null;

// Werte kommen jetzt aus der scores-Tabelle (players hat keine streak/score-Spalten)
const s = allStats[String(user.id)] || { total_score: 0, games_played: 0, unique_games: 0, streak: 0 };

const streak = Number(s.streak) || 0;
const score = Number(s.total_score) || 0;
const gamesPlayed = Number(s.games_played) || 0;
const uniqueGames = Number(s.unique_games) || 0;

// noch nicht gespielte Games
const moreGames = Math.max(allGames.length - uniqueGames, 0);

const playUrl = featured
  ? `${PLATFORM_URL}/player-dashboard?game=${featured.id}`
  : `${PLATFORM_URL}/player-dashboard`;

return [{
  json: {
    user_id: user.id,
    user_name: user.display_name,
    user_role: user.role,
    user_email: user.email,
    featured_game: featured,
    streak,
    score,
    games_played: gamesPlayed,
    unique_games: uniqueGames,
    more_games_count: moreGames,
    play_url: playUrl,
    dashboard_url: `${PLATFORM_URL}/player-dashboard`,
  }
}];
